// GENERATED by extension/scripts/gen-app-changelogs.mjs from each app's CHANGELOG.md —
// do not edit by hand.
//
// An app's CHANGELOG.md owns its version: the newest entry IS the version. There is no
// `version` field in meta.ts, on purpose — a second place is a place to drift, and it did.

export interface AppRelease {
  version: string;
  date: string;
  /** Clean one-line bullets — no marker, no issue ref, no comments. */
  lines: string[];
}

