/** The app's version — its newest release. The only place this is declared. */
export const appVersion = (id: string): string => APP_CHANGELOGS[id]?.[0]?.version ?? '';

/** The app's first-release date — its OLDEST entry. Drives the "New" badge (#1114): an app
 *  is new for NEW_APP_DAYS from this date (see `isNewApp` in @kimtos/config). Empty when the
 *  app has no changelog, which reads as "not new". */
export const appFirstReleased = (id: string): string => APP_CHANGELOGS[id]?.at(-1)?.date ?? '';

/** The app's releases, newest first. */
export const appReleases = (id: string): AppRelease[] => APP_CHANGELOGS[id] ?? [];
